-- Consolidated source-control migration for the compensation credit correction lifecycle
-- and Needs Attention read model. This captures the live Supabase state added on 2026-09-09.

create table if not exists public.comp_credit_correction_requests (
  id uuid primary key default gen_random_uuid(),
  candidate_key text not null,
  hubspot_deal_id text not null,
  plan_component_id uuid not null references public.comp_plan_components(id),
  earning_id uuid references public.comp_earnings(id),
  current_employee_id uuid not null references public.employees(id),
  requested_employee_id uuid not null references public.employees(id),
  current_credit_percentage numeric not null,
  requested_credit_percentage numeric not null check (requested_credit_percentage > 0 and requested_credit_percentage <= 100),
  reason text not null check (length(trim(reason)) >= 8),
  status text not null default 'pending_review',
  requested_by uuid not null,
  requested_at timestamptz not null default now(),
  resolved_by uuid,
  resolved_at timestamptz,
  resolution_notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  correction_path text not null default 'direct',
  replacement_earning_id uuid references public.comp_earnings(id)
);

alter table public.comp_credit_correction_requests add column if not exists correction_path text not null default 'direct';
alter table public.comp_credit_correction_requests add column if not exists replacement_earning_id uuid references public.comp_earnings(id);
alter table public.comp_credit_correction_requests drop constraint if exists comp_credit_correction_requests_status_check;
alter table public.comp_credit_correction_requests add constraint comp_credit_correction_requests_status_check check (status = any(array['pending_review','approved_for_correction','ready_to_apply','adjustment_pending','rejected','cancelled','applied']::text[]));
alter table public.comp_credit_correction_requests drop constraint if exists comp_credit_correction_requests_correction_path_check;
alter table public.comp_credit_correction_requests add constraint comp_credit_correction_requests_correction_path_check check (correction_path = any(array['direct','reopen_required','paid_adjustment']::text[]));

alter table public.comp_credit_correction_requests enable row level security;
drop policy if exists "credit corrections view permitted" on public.comp_credit_correction_requests;
create policy "credit corrections view permitted" on public.comp_credit_correction_requests for select to authenticated using (auth.uid() is not null and private.has_permission('earnings.view'));
drop policy if exists "credit corrections create permitted" on public.comp_credit_correction_requests;
create policy "credit corrections create permitted" on public.comp_credit_correction_requests for insert to authenticated with check (auth.uid() is not null and requested_by=auth.uid() and (private.has_permission('earnings.edit') or private.has_permission('earnings.override')));
drop policy if exists "credit corrections update permitted" on public.comp_credit_correction_requests;
create policy "credit corrections update permitted" on public.comp_credit_correction_requests for update to authenticated using (auth.uid() is not null and (private.has_permission('earnings.edit') or private.has_permission('earnings.override'))) with check (auth.uid() is not null and (private.has_permission('earnings.edit') or private.has_permission('earnings.override')));
revoke all on public.comp_credit_correction_requests from anon;

create or replace function public.get_comp_credit_correction_targets() returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if;
 if not (private.has_permission('earnings.edit') or private.has_permission('earnings.override')) then raise exception 'Permission denied.' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'full_name',full_name,'email',email) order by full_name),'[]'::jsonb) into result from public.employees where is_active=true;
 return result;
end;$$;

create or replace function public.validate_comp_credit_correction_target(target_candidate_key text,target_employee_id uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.comp_deal_earning_candidates_v2%rowtype; source_component public.comp_plan_components%rowtype; source_version public.comp_plan_versions%rowtype; target_assignment public.employee_plan_assignments%rowtype; target_component public.comp_plan_components%rowtype; target_version public.comp_plan_versions%rowtype; target_name text;
begin
 if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if;
 if not (private.has_permission('earnings.edit') or private.has_permission('earnings.override')) then raise exception 'Permission denied.' using errcode='42501'; end if;
 select * into c from public.comp_deal_earning_candidates_v2 where candidate_key=target_candidate_key; if not found then raise exception 'Compensation candidate not found.' using errcode='P0002'; end if;
 select * into source_component from public.comp_plan_components where id=c.plan_component_id; select * into source_version from public.comp_plan_versions where id=source_component.plan_version_id;
 select full_name into target_name from public.employees where id=target_employee_id and is_active=true; if target_name is null then return jsonb_build_object('valid',false,'status','inactive_employee','message','The requested employee is not active.'); end if;
 select epa.* into target_assignment from public.employee_plan_assignments epa join public.comp_plan_versions pv on pv.id=epa.plan_version_id where epa.employee_id=target_employee_id and c.earned_date>=epa.effective_start_date and (epa.effective_end_date is null or c.earned_date<=epa.effective_end_date) and c.earned_date>=epa.earnings_eligibility_date and pv.comp_plan_id=source_version.comp_plan_id order by epa.effective_start_date desc limit 1;
 if not found then return jsonb_build_object('valid',false,'status','plan_resolution_required','message',target_name||' does not have the applicable compensation plan assigned for the earning date.','employee_name',target_name,'earned_date',c.earned_date,'source_component_code',source_component.component_code); end if;
 select * into target_version from public.comp_plan_versions where id=target_assignment.plan_version_id;
 select * into target_component from public.comp_plan_components where plan_version_id=target_assignment.plan_version_id and component_code=source_component.component_code and is_active=true limit 1;
 if not found then return jsonb_build_object('valid',false,'status','component_resolution_required','message',target_name||' has a plan assignment for the earning date, but that plan version does not contain the applicable compensation component.','employee_name',target_name,'earned_date',c.earned_date,'source_component_code',source_component.component_code,'target_plan_version_id',target_assignment.plan_version_id); end if;
 if target_version.status::text not in ('active','approved') then return jsonb_build_object('valid',false,'status','plan_version_not_active','message','The matching target plan version is not active or approved.','employee_name',target_name,'target_plan_version_id',target_version.id,'target_plan_version_status',target_version.status); end if;
 return jsonb_build_object('valid',true,'status','compatible','message','Target employee has a compatible plan and component for the earning date.','employee_name',target_name,'earned_date',c.earned_date,'target_plan_assignment_id',target_assignment.id,'target_plan_version_id',target_version.id,'target_plan_component_id',target_component.id,'component_code',target_component.component_code);
end;$$;

create or replace function public.preview_comp_credit_correction_replacement(target_candidate_key text,target_employee_id uuid,target_credit_percentage numeric) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.comp_deal_earning_candidates_v2%rowtype; compatibility jsonb; target_assignment_id uuid; target_component_id uuid; target_component public.comp_plan_components%rowtype; target_period public.comp_periods%rowtype; existing_calc public.comp_calculations%rowtype; source_amount numeric; credited_basis numeric; corrected_earned numeric; rate numeric; calc_type text; target_name text;
begin
 if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if;
 if not (private.has_permission('earnings.edit') or private.has_permission('earnings.override')) then raise exception 'Permission denied.' using errcode='42501'; end if;
 if target_credit_percentage is null or target_credit_percentage<=0 or target_credit_percentage>100 then raise exception 'Credit percentage must be greater than 0 and no more than 100.' using errcode='22023'; end if;
 select * into c from public.comp_deal_earning_candidates_v2 where candidate_key=target_candidate_key; if not found then raise exception 'Compensation candidate not found.' using errcode='P0002'; end if;
 compatibility:=public.validate_comp_credit_correction_target(target_candidate_key,target_employee_id); if not coalesce((compatibility->>'valid')::boolean,false) then return jsonb_build_object('valid',false,'status',compatibility->>'status','validation',compatibility); end if;
 target_assignment_id:=(compatibility->>'target_plan_assignment_id')::uuid; target_component_id:=(compatibility->>'target_plan_component_id')::uuid;
 select * into target_component from public.comp_plan_components where id=target_component_id; select full_name into target_name from public.employees where id=target_employee_id;
 select * into target_period from public.comp_periods where c.earned_date between start_date and end_date order by start_date desc limit 1; if not found then return jsonb_build_object('valid',false,'status','comp_period_missing','message','No compensation period exists for the earning date.','earned_date',c.earned_date,'validation',compatibility); end if;
 select * into existing_calc from public.comp_calculations where employee_id=target_employee_id and comp_period_id=target_period.id order by calculation_version desc limit 1;
 source_amount:=coalesce(c.source_amount,0); credited_basis:=round(source_amount*(target_credit_percentage/100.0),2); calc_type:=target_component.calculation_type;
 if calc_type='percentage' then rate:=nullif(target_component.rule_configuration->>'rate','')::numeric; if rate is null then return jsonb_build_object('valid',false,'status','component_rule_incomplete','message','The target percentage component has no rate configured.'); end if; corrected_earned:=round(credited_basis*rate,2);
 elsif calc_type in ('fixed','fixed_amount') then corrected_earned:=coalesce(nullif(target_component.rule_configuration->>'amount','')::numeric,nullif(target_component.rule_configuration->>'fixed_amount','')::numeric,0); rate:=null;
 else return jsonb_build_object('valid',false,'status','unsupported_calculation_type','message','Replacement preview does not yet support this calculation type.','calculation_type',calc_type); end if;
 return jsonb_build_object('valid',true,'status','ready_for_replacement_preview','candidate_key',c.candidate_key,'hubspot_deal_id',c.hubspot_deal_id,'deal_name',c.deal_name,'company_name',c.company_name,'earned_date',c.earned_date,'source_amount',source_amount,'original_employee_id',c.employee_id,'original_employee_name',c.full_name,'original_credit_percentage',c.credit_percentage,'original_earned_amount',c.calculated_earning_amount,'target_employee_id',target_employee_id,'target_employee_name',target_name,'target_credit_percentage',target_credit_percentage,'credited_basis',credited_basis,'target_plan_assignment_id',target_assignment_id,'target_plan_component_id',target_component_id,'target_component_name',target_component.name,'target_component_code',target_component.component_code,'calculation_type',calc_type,'rate',rate,'corrected_earned_amount',corrected_earned,'comp_period_id',target_period.id,'comp_period_name',target_period.name,'comp_period_status',target_period.status,'existing_calculation_id',existing_calc.id,'existing_calculation_version',existing_calc.calculation_version,'calculation_container_action',case when existing_calc.id is null then 'create_for_target_employee_period' else 'create_next_version_for_target_employee_period' end,'workflow_restart_required',true,'validation',compatibility);
end;$$;

create or replace function public.request_comp_credit_correction(target_candidate_key text,target_employee_id uuid,target_credit_percentage numeric,correction_reason text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare actor uuid:=auth.uid(); c public.comp_deal_earning_candidates_v2%rowtype; e public.comp_earnings%rowtype; request_id uuid; normalized_reason text:=nullif(trim(coalesce(correction_reason,'')),''); path text:='direct';
begin
 if actor is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not (private.has_permission('earnings.edit') or private.has_permission('earnings.override')) then raise exception 'You are not permitted to request compensation credit corrections.' using errcode='42501'; end if;
 if normalized_reason is null or length(normalized_reason)<8 then raise exception 'A correction reason of at least 8 characters is required.' using errcode='22023'; end if; if target_credit_percentage is null or target_credit_percentage<=0 or target_credit_percentage>100 then raise exception 'Credit percentage must be greater than 0 and no more than 100.' using errcode='22023'; end if;
 select * into c from public.comp_deal_earning_candidates_v2 where candidate_key=target_candidate_key; if not found then raise exception 'Compensation candidate not found.' using errcode='P0002'; end if;
 select * into e from public.comp_earnings ce where ce.is_current and ce.employee_id=c.employee_id and ce.source_external_id=c.hubspot_deal_id and ce.plan_component_id=c.plan_component_id order by ce.created_at desc limit 1;
 if found then if e.payment_status in ('paid','partially_paid') or coalesce(e.paid_amount,0)>0 then path:='paid_adjustment'; elsif e.employee_verification_status='verified' or e.manager_approval_status in ('approved','returned','rejected') or e.executive_approval_status='approved' or coalesce(e.approved_amount,0)>0 or e.finance_accepted_at is not null then path:='reopen_required'; end if; end if;
 if exists(select 1 from public.comp_credit_correction_requests r where r.candidate_key=target_candidate_key and r.status in ('pending_review','approved_for_correction','ready_to_apply','adjustment_pending')) then raise exception 'An open credit correction already exists for this transaction.' using errcode='22023'; end if;
 insert into public.comp_credit_correction_requests(candidate_key,hubspot_deal_id,plan_component_id,earning_id,current_employee_id,requested_employee_id,current_credit_percentage,requested_credit_percentage,reason,requested_by,correction_path) values(c.candidate_key,c.hubspot_deal_id,c.plan_component_id,case when found then e.id else null end,c.employee_id,target_employee_id,coalesce(c.credit_percentage,100),target_credit_percentage,normalized_reason,actor,path) returning id into request_id;
 insert into public.app_access_audit_events(actor_user_id,event_type,event_reason,previous_state,new_state,related_employee_id) values(actor,'comp_credit_correction_requested',normalized_reason,jsonb_build_object('candidate_key',c.candidate_key,'employee_id',c.employee_id,'credit_percentage',c.credit_percentage),jsonb_build_object('correction_request_id',request_id,'requested_employee_id',target_employee_id,'requested_credit_percentage',target_credit_percentage,'status','pending_review','correction_path',path),c.employee_id);
 return jsonb_build_object('status','pending_review','correction_request_id',request_id,'candidate_key',c.candidate_key,'correction_path',path);
end;$$;

create or replace function public.review_comp_credit_correction(target_request_id uuid,requested_decision text,review_notes text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare actor uuid:=auth.uid(); r public.comp_credit_correction_requests%rowtype; normalized_notes text:=nullif(trim(coalesce(review_notes,'')),'');
begin
 if actor is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not private.has_permission('earnings.override') then raise exception 'You are not permitted to review compensation credit corrections.' using errcode='42501'; end if;
 if requested_decision not in ('approved_for_correction','rejected','cancelled') then raise exception 'Invalid correction review decision.' using errcode='22023'; end if; if normalized_notes is null or length(normalized_notes)<4 then raise exception 'Review notes are required.' using errcode='22023'; end if;
 select * into r from public.comp_credit_correction_requests where id=target_request_id for update; if not found then raise exception 'Correction request not found.' using errcode='P0002'; end if; if r.status<>'pending_review' then raise exception 'This correction request is no longer pending review.' using errcode='22023'; end if;
 update public.comp_credit_correction_requests set status=requested_decision,resolved_by=actor,resolved_at=now(),resolution_notes=normalized_notes,updated_at=now() where id=r.id;
 insert into public.app_access_audit_events(actor_user_id,event_type,event_reason,previous_state,new_state,related_employee_id) values(actor,'comp_credit_correction_reviewed',normalized_notes,jsonb_build_object('correction_request_id',r.id,'status',r.status),jsonb_build_object('correction_request_id',r.id,'status',requested_decision,'reviewed_by',actor),r.current_employee_id);
 return jsonb_build_object('status',requested_decision,'correction_request_id',r.id);
end;$$;

create or replace function public.get_comp_credit_correction_queue() returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not (private.has_permission('earnings.edit') or private.has_permission('earnings.override')) then raise exception 'Permission denied.' using errcode='42501'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'candidate_key',r.candidate_key,'hubspot_deal_id',r.hubspot_deal_id,'earning_id',r.earning_id,'current_employee_id',r.current_employee_id,'current_employee_name',ce.full_name,'requested_employee_id',r.requested_employee_id,'requested_employee_name',re.full_name,'current_credit_percentage',r.current_credit_percentage,'requested_credit_percentage',r.requested_credit_percentage,'reason',r.reason,'status',r.status,'correction_path',r.correction_path,'requested_at',r.requested_at,'resolution_notes',r.resolution_notes,'resolved_at',r.resolved_at,'earning_payment_status',e.payment_status,'earning_paid_amount',e.paid_amount,'earning_approved_amount',e.approved_amount,'employee_verification_status',e.employee_verification_status,'manager_approval_status',e.manager_approval_status,'executive_approval_status',e.executive_approval_status,'replacement_earning_id',r.replacement_earning_id) order by r.requested_at desc),'[]'::jsonb) into result from public.comp_credit_correction_requests r left join public.employees ce on ce.id=r.current_employee_id left join public.employees re on re.id=r.requested_employee_id left join public.comp_earnings e on e.id=r.earning_id;
 return result;
end;$$;

-- process_comp_credit_correction and apply_comp_credit_correction_replacement are intentionally
-- kept as database-only atomic functions. They are redefined below to ensure a fresh environment
-- has the same lifecycle guardrails as production.
create or replace function public.process_comp_credit_correction(target_request_id uuid,processing_reason text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare actor uuid:=auth.uid(); r public.comp_credit_correction_requests%rowtype; e public.comp_earnings%rowtype; normalized_reason text:=nullif(trim(coalesce(processing_reason,'')),''); adj_id uuid; compatibility jsonb;
begin
 if actor is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not private.has_permission('earnings.override') then raise exception 'Permission denied.' using errcode='42501'; end if; if normalized_reason is null or length(normalized_reason)<8 then raise exception 'A processing reason of at least 8 characters is required.' using errcode='22023'; end if;
 select * into r from public.comp_credit_correction_requests where id=target_request_id for update; if not found then raise exception 'Correction request not found.' using errcode='P0002'; end if; if r.status<>'approved_for_correction' then raise exception 'Correction must be approved before processing.' using errcode='22023'; end if;
 compatibility:=public.validate_comp_credit_correction_target(r.candidate_key,r.requested_employee_id); if not coalesce((compatibility->>'valid')::boolean,false) then return jsonb_build_object('status','plan_resolution_required','correction_path',r.correction_path,'correction_request_id',r.id,'validation',compatibility); end if;
 if r.earning_id is not null then select * into e from public.comp_earnings where id=r.earning_id for update; end if;
 if r.correction_path='direct' then update public.comp_credit_correction_requests set status='ready_to_apply',resolution_notes=concat_ws(E'\n',resolution_notes,normalized_reason),updated_at=now() where id=r.id; return jsonb_build_object('status','ready_to_apply','correction_path',r.correction_path,'correction_request_id',r.id,'validation',compatibility);
 elsif r.correction_path='reopen_required' then if r.earning_id is null then raise exception 'No earning is linked to this correction.' using errcode='22023'; end if; if e.payment_status in ('paid','partially_paid') or coalesce(e.paid_amount,0)>0 then raise exception 'This earning now has payment history. Use the paid adjustment path.' using errcode='22023'; end if; update public.approval_requests set status='returned',completed_at=now(),notes=concat_ws(E'\n',notes,'Returned for attribution correction: '||normalized_reason) where comp_earning_id=e.id and status='pending'; update public.comp_earnings set employee_verification_status='correction_requested',manager_approval_status='returned',executive_approval_status='returned',payment_status='not_payable',finance_accepted_by=null,finance_accepted_at=null,expected_payment_date=null,expected_pay_period_label=null,expected_pay_period_start=null,expected_pay_period_end=null,updated_at=now() where id=e.id; update public.comp_credit_correction_requests set status='ready_to_apply',resolution_notes=concat_ws(E'\n',resolution_notes,normalized_reason),updated_at=now() where id=r.id; return jsonb_build_object('status','ready_to_apply','correction_path',r.correction_path,'correction_request_id',r.id,'earning_id',e.id,'validation',compatibility);
 elsif r.correction_path='paid_adjustment' then if r.earning_id is null then raise exception 'No paid earning is linked to this correction.' using errcode='22023'; end if; if not (e.payment_status in ('paid','partially_paid') or coalesce(e.paid_amount,0)>0) then raise exception 'This earning no longer has paid history; re-evaluate the correction path.' using errcode='22023'; end if; insert into public.earning_adjustments(employee_id,comp_earning_id,comp_period_id,adjustment_type,amount,reason,requested_by,approval_status,effective_date,supporting_details) values(e.employee_id,e.id,null,'correction',-abs(coalesce(nullif(e.paid_amount,0),e.earned_amount,0)),normalized_reason,actor,'pending',current_date,jsonb_build_object('correction_request_id',r.id,'requested_employee_id',r.requested_employee_id,'requested_credit_percentage',r.requested_credit_percentage,'purpose','preserve_paid_history_and_reverse_for_replacement')) returning id into adj_id; update public.comp_credit_correction_requests set status='adjustment_pending',resolution_notes=concat_ws(E'\n',resolution_notes,normalized_reason),updated_at=now() where id=r.id; return jsonb_build_object('status','adjustment_pending','correction_path',r.correction_path,'correction_request_id',r.id,'adjustment_id',adj_id,'earning_id',e.id,'validation',compatibility); end if;
 raise exception 'Unknown correction path.' using errcode='22023';
end;$$;

create or replace function public.apply_comp_credit_correction_replacement(target_request_id uuid,application_reason text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare actor uuid:=auth.uid(); r public.comp_credit_correction_requests%rowtype; e public.comp_earnings%rowtype; p jsonb; period_id uuid; calc_id uuid; replacement_id uuid; next_version int; earned numeric; eligible numeric; exec_required boolean; normalized_reason text:=nullif(trim(coalesce(application_reason,'')),'');
begin
 if actor is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not private.has_permission('earnings.override') then raise exception 'Permission denied.' using errcode='42501'; end if; if normalized_reason is null or length(normalized_reason)<8 then raise exception 'An application reason of at least 8 characters is required.' using errcode='22023'; end if;
 select * into r from public.comp_credit_correction_requests where id=target_request_id for update; if not found then raise exception 'Correction request not found.' using errcode='P0002'; end if; if r.status<>'ready_to_apply' then raise exception 'Correction must be processed to ready_to_apply before replacement.' using errcode='22023'; end if; if r.correction_path='paid_adjustment' then raise exception 'Paid corrections require the approved adjustment/reversal path before replacement.' using errcode='22023'; end if; if r.replacement_earning_id is not null then raise exception 'This correction already has a replacement earning.' using errcode='22023'; end if; if r.earning_id is null then raise exception 'No source earning is linked to this correction.' using errcode='22023'; end if;
 select * into e from public.comp_earnings where id=r.earning_id for update; if not found or not e.is_current then raise exception 'Source earning is no longer current.' using errcode='22023'; end if; if e.payment_status in ('paid','partially_paid') or coalesce(e.paid_amount,0)>0 then raise exception 'Source earning now has payment history. Use the paid adjustment path.' using errcode='22023'; end if;
 p:=public.preview_comp_credit_correction_replacement(r.candidate_key,r.requested_employee_id,r.requested_credit_percentage); if not coalesce((p->>'valid')::boolean,false) then return jsonb_build_object('status','replacement_blocked','correction_request_id',r.id,'preview',p); end if;
 period_id:=(p->>'comp_period_id')::uuid; earned:=(p->>'corrected_earned_amount')::numeric; select coalesce(max(calculation_version),0)+1 into next_version from public.comp_calculations where employee_id=r.requested_employee_id and comp_period_id=period_id; eligible:=case when e.eligibility_status in ('eligible','waived') then earned else 0 end; select exists(select 1 from public.employee_approval_chains ac where ac.employee_id=r.requested_employee_id and ac.is_required=true and ac.approval_level='executive_approval' and e.earned_date>=ac.effective_start_date and (ac.effective_end_date is null or e.earned_date<=ac.effective_end_date)) into exec_required;
 insert into public.comp_calculations(employee_id,comp_period_id,calculation_version,calculated_at,calculated_by,total_earned,total_eligible,total_approved,total_paid,notes) values(r.requested_employee_id,period_id,next_version,now(),actor,earned,eligible,0,0,'Replacement calculation created by approved attribution correction '||r.id) returning id into calc_id;
 insert into public.comp_earnings(calculation_id,employee_id,plan_assignment_id,plan_component_id,earning_name,earning_description,source_type,source_external_id,source_url,source_snapshot,earned_date,earned_amount,eligibility_status,eligibility_condition_type,eligibility_condition_description,eligibility_due_date,eligible_date,eligible_amount,eligibility_evidence,employee_verification_status,manager_approval_status,executive_approval_required,executive_approval_status,approved_amount,payment_status,paid_amount,supersedes_earning_id,is_current,earning_origin,reconciliation_status,source_match_status,historical_reference,reconciliation_notes) values(calc_id,r.requested_employee_id,(p->>'target_plan_assignment_id')::uuid,(p->>'target_plan_component_id')::uuid,p->>'target_component_name',e.earning_description,e.source_type,e.source_external_id,e.source_url,e.source_snapshot||jsonb_build_object('candidate_key',r.candidate_key,'credit_percentage',r.requested_credit_percentage,'correction_request_id',r.id),e.earned_date,earned,e.eligibility_status,e.eligibility_condition_type,e.eligibility_condition_description,e.eligibility_due_date,e.eligible_date,eligible,e.eligibility_evidence||jsonb_build_object('correction_request_id',r.id),'pending_employee','pending',exec_required,case when exec_required then 'pending' else 'not_required' end,0,'not_payable',0,e.id,true,e.earning_origin,'not_reviewed',e.source_match_status,e.historical_reference,'Replacement created from approved attribution correction; original history retained.') returning id into replacement_id;
 update public.comp_earnings set is_current=false,updated_at=now() where id=e.id; update public.comp_credit_correction_requests set status='applied',replacement_earning_id=replacement_id,resolved_by=actor,resolved_at=now(),resolution_notes=concat_ws(E'\n',resolution_notes,normalized_reason),updated_at=now() where id=r.id;
 insert into public.app_access_audit_events(actor_user_id,event_type,event_reason,previous_state,new_state,related_employee_id) values(actor,'comp_credit_correction_replacement_applied',normalized_reason,jsonb_build_object('correction_request_id',r.id,'source_earning_id',e.id,'source_employee_id',e.employee_id,'source_amount',e.earned_amount),jsonb_build_object('replacement_earning_id',replacement_id,'replacement_employee_id',r.requested_employee_id,'replacement_amount',earned,'calculation_id',calc_id,'calculation_version',next_version),r.requested_employee_id);
 return jsonb_build_object('status','applied','correction_request_id',r.id,'source_earning_id',e.id,'replacement_earning_id',replacement_id,'calculation_id',calc_id,'calculation_version',next_version,'preview',p);
end;$$;

create or replace function public.get_comp_attention_workspace_data() returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if; if not (private.has_permission('workspace.view_administration') or private.has_permission('earnings.view') or private.has_permission('earnings.override') or private.has_permission('payments.view')) then raise exception 'Permission denied.' using errcode='42501'; end if;
 select jsonb_build_object('metrics',jsonb_build_object('missing_plan_assignment',(select count(*) from public.employees e where e.is_active and not exists(select 1 from public.employee_plan_assignments a where a.employee_id=e.id and current_date between a.effective_start_date and coalesce(a.effective_end_date,'9999-12-31'))),'waiting_eligibility',(select count(*) from public.comp_earnings where is_current and eligibility_status='pending_condition'),'returned_or_correction',(select count(*) from public.comp_earnings where is_current and (employee_verification_status='correction_requested' or manager_approval_status='returned' or executive_approval_status='returned')),'ready_for_payroll',(select count(*) from public.comp_earnings where is_current and payment_status='ready_for_payroll'),'open_credit_reviews',(select count(*) from public.comp_deal_credit_reviews where review_status='pending'),'open_corrections',(select count(*) from public.comp_credit_correction_requests where status in ('pending_review','approved_for_correction','ready_to_apply','adjustment_pending'))),'missing_plan_assignments',coalesce((select jsonb_agg(jsonb_build_object('employee_id',e.id,'employee_name',e.full_name,'email',e.email) order by e.full_name) from public.employees e where e.is_active and not exists(select 1 from public.employee_plan_assignments a where a.employee_id=e.id and current_date between a.effective_start_date and coalesce(a.effective_end_date,'9999-12-31'))),'[]'::jsonb),'waiting_eligibility',coalesce((select jsonb_agg(jsonb_build_object('earning_id',ce.id,'employee_id',ce.employee_id,'employee_name',e.full_name,'earning_name',ce.earning_name,'earned_amount',ce.earned_amount,'earned_date',ce.earned_date,'condition',ce.eligibility_condition_description,'source_external_id',ce.source_external_id) order by ce.earned_date desc) from public.comp_earnings ce join public.employees e on e.id=ce.employee_id where ce.is_current and ce.eligibility_status='pending_condition'),'[]'::jsonb),'returned_or_correction',coalesce((select jsonb_agg(jsonb_build_object('earning_id',ce.id,'employee_id',ce.employee_id,'employee_name',e.full_name,'earning_name',ce.earning_name,'earned_amount',ce.earned_amount,'employee_verification_status',ce.employee_verification_status,'manager_approval_status',ce.manager_approval_status,'executive_approval_status',ce.executive_approval_status) order by ce.updated_at desc) from public.comp_earnings ce join public.employees e on e.id=ce.employee_id where ce.is_current and (ce.employee_verification_status='correction_requested' or ce.manager_approval_status='returned' or ce.executive_approval_status='returned')),'[]'::jsonb),'ready_for_payroll',coalesce((select jsonb_agg(jsonb_build_object('earning_id',ce.id,'employee_id',ce.employee_id,'employee_name',e.full_name,'earning_name',ce.earning_name,'approved_amount',ce.approved_amount,'expected_pay_period_label',ce.expected_pay_period_label) order by ce.updated_at desc) from public.comp_earnings ce join public.employees e on e.id=ce.employee_id where ce.is_current and ce.payment_status='ready_for_payroll'),'[]'::jsonb),'open_corrections',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'hubspot_deal_id',r.hubspot_deal_id,'status',r.status,'correction_path',r.correction_path,'current_employee_id',r.current_employee_id,'requested_employee_id',r.requested_employee_id,'requested_at',r.requested_at) order by r.requested_at desc) from public.comp_credit_correction_requests r where r.status in ('pending_review','approved_for_correction','ready_to_apply','adjustment_pending')),'[]'::jsonb)) into result;
 return result;
end;$$;

